function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(e=>{const d=dictionary[e.dataset.i18n];if(d)e.innerHTML=d[lang==='id'?0:1];});const b=document.querySelector('#language');if(b){b.innerHTML=lang==='id'?'ID <span>/ EN</span>':'EN <span>/ ID</span>';b.setAttribute('aria-label',lang==='id'?'Switch language to English':'Ganti bahasa ke Indonesia');}renderProducts();}
export function toast(message){const el=document.querySelector('#toast');if(!el)return;el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',6000);}
const errors={SERVICE_NOT_CONFIGURED:['Layanan akun belum dikonfigurasi.','Account service is not configured yet.'],CHECKOUT_CLOSED:['Pembayaran belum dibuka.','Payments are not open yet.'],SIGN_IN_REQUIRED:['Silakan masuk terlebih dahulu.','Please sign in first.'],SESSION_EXPIRED:['Sesi berakhir. Silakan masuk kembali.','Your session expired. Please sign in again.'],PURCHASE_REQUIRED:['Produk ini belum dimiliki akun Anda.','This account does not own this product.'],ALREADY_OWNED:['Anda sudah memiliki produk ini.','You already own this product.'],ADMIN_REQUIRED:['Akun ini tidak memiliki akses admin.','This account does not have admin access.'],ACCOUNT_BLOCKED:['Akses akun dibatasi. Hubungi pengelola.','Account access is restricted. Contact the administrator.'],CHECKOUT_RATE_LIMIT:['Tunggu sebentar sebelum mencoba pembayaran lagi.','Please wait before starting another checkout.'],PRODUCT_FILE_NOT_READY:['File produk belum siap.','The product file is not ready yet.']};
export function errorMessage(e){const t=errors[e.message];return t?t[lang==='id'?0:1]:tr('Permintaan belum berhasil. Coba lagi nanti.','The request could not be completed. Please try again later.');}
async function authRequest(endpoint,body){const r=await fetch(config.supabaseUrl+'/auth/v1/'+endpoint,{method:'POST',headers:{apikey:config.anonKey,'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.msg||d.message||d.error_description||'AUTH_FAILED');return d;}
function saveSession(d){session=d.access_token?{access_token:d.access_token,refresh_token:d.refresh_token,expires_at:Date.now()+d.expires_in*1000}:null;if(session)sessionStorage.setItem('om-session',JSON.stringify(session));else sessionStorage.removeItem('om-session');}
export const signedIn = () => !!session;
const invite = new URLSearchParams(location.search).get('ref');
if (/^[A-F0-9]{12}$/i.test(invite || '')) sessionStorage.setItem('om-affiliate-invite',invite.toUpperCase());
export async function affiliateRpc(action,payload) {
 if (!session) throw new Error('SIGN_IN_REQUIRED');
 if (session.expires_at < Date.now()+30000) saveSession(await authRequest('token?grant_type=refresh_token',{refresh_token:session.refresh_token}));
 const response = await fetch(config.supabaseUrl+'/rest/v1/rpc/affiliate_'+action,{
   method:'POST',headers:{apikey:config.anonKey,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},
   body:JSON.stringify(payload)
 });
 if (!response.ok) throw new Error('AFFILIATE_UNAVAILABLE');
 return response.json();
}
async function recordReferral(code) {
 if (!code) return;
 try {
   const result = await affiliateRpc('redeem',{p_code:code});
   const messages = {credited:'Referral tercatat.',already_linked:'Akun ini sudah memiliki referral.',self:'Kode sendiri tidak dapat dipakai.',invalid:'Kode afiliasi tidak ditemukan.',login_required:'Masuk kembali untuk memakai kode afiliasi.'};
   sessionStorage.removeItem('om-affiliate-invite');
   toast(messages[result] || 'Kode belum diterapkan.');
 } catch { toast('Login berhasil. Referral belum tercatat. Coba kembali saat login berikutnya.'); }
}
export async function api(path,body,raw=false){
 if(session&&session.expires_at<Date.now()+30000){try{saveSession(await authRequest('token?grant_type=refresh_token',{refresh_token:session.refresh_token}));}catch{saveSession({});throw new Error('SESSION_EXPIRED');}}
 const r=await fetch(API_BASE+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(session?{Authorization:'Bearer '+session.access_token}:{})},...(body?{body:JSON.stringify(body)}:{})});
 if(!r.ok){let d;try{d=await r.json();}catch{d={error:'SERVICE_NOT_CONFIGURED'};}throw new Error(d.error||'SERVICE_NOT_CONFIGURED');}return raw?r.text():r.json();
}
export const ready=(async()=>{try{const r=await fetch(API_BASE+'config');if(r.ok&&r.headers.get('content-type')?.includes('application/json'))config=await r.json();}catch{}try{const p=await api('products');if(Array.isArray(p))products=p.map(v=>({...fallbackProducts.find(x=>x.id===v.id),...v}));}catch{}renderProducts();return config;})();
function renderProducts(){const el=document.querySelector('#products');if(!el)return;el.innerHTML=products.filter(p=>filter==='all'||p.category===filter).map(p=>`<article class="product"><div class="product-image"><img src="foto/${encodeURIComponent(p.id)}-desktop.png" alt="${escapeHtml(p.title)} — ${tr('pratinjau simulator','simulator preview')}" loading="lazy"><span class="product-tag">${p.is_free?tr('GRATIS','FREE WORKSPACE'):'PREMIUM'}</span></div><div class="product-body"><p class="product-kind">${escapeHtml(p.category)} / 3D WORKSPACE</p><h3>${escapeHtml(p.title)}</h3><p class="product-description">${escapeHtml(lang==='en'?(p.en||p.description):p.description)}</p><p class="product-price">${money(p.price_idr)}<small>${p.is_free?tr('Jelajahi sekarang','Explore now'):tr('sekali bayar','one-time payment')}</small></p>${p.is_free?`<a class="btn primary" href="workspace.html">${tr('Buka workspace','Open workspace')}</a>`:`<button class="btn" data-product="${escapeHtml(p.id)}">${tr('Lihat akses','View access')}</button>`}</div></article>`).join('');el.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>openProduct(b.dataset.product));}
export async function showAccount(){await ready;const dialog=document.querySelector('#account-dialog'),content=document.querySelector('#account-content');if(!dialog||!content)return;content.replaceChildren();dialog.showModal();if(!config.authReady){content.innerHTML=`<p class="notice">${tr('Akun dan pembayaran sedang disiapkan. Anda tetap bisa menggunakan simulator Shinko gratis tanpa login.','Accounts and payments are being prepared. Explore the free Shinko simulator without signing in.')}</p><a class="btn primary" href="workspace.html">${tr('Coba simulator gratis','Try the free simulator')}</a>`;return;}if(session){try{const me=await api('me');content.innerHTML=`<p>${escapeHtml(me.email)}</p><h3>${tr('Workspace saya','My workspaces')}</h3><ul class="account-list">${(me.admin?products.filter(p=>!p.is_free).map(p=>({product_id:p.id})):me.access).map(a=>`<li><a class="btn" href="workspace.html?product=${encodeURIComponent(a.product_id)}">${escapeHtml(products.find(p=>p.id===a.product_id)?.title||a.product_id)}</a></li>`).join('')||`<li>${tr('Belum ada produk premium.','No premium products yet.')}</li>`}</ul><h3>${tr('Transaksi','Orders')}</h3><ul class="account-list">${me.orders.map(o=>`<li>${escapeHtml(o.product_id)} — ${money(o.amount_idr)}<p>${escapeHtml(o.status)} · ${escapeHtml(o.id)}</p><button class="btn" data-sync="${escapeHtml(o.id)}">${tr('Periksa pembayaran','Check payment')}</button></li>`).join('')||`<li>${tr('Belum ada transaksi.','No orders yet.')}</li>`}</ul><div class="row">${me.admin?'<a class="btn" href="admin.html">Admin</a>':''}<button class="btn" id="signout">${tr('Keluar','Sign out')}</button></div>`;content.querySelector('#signout').onclick=async()=>{try{await fetch(config.supabaseUrl+'/auth/v1/logout',{method:'POST',headers:{apikey:config.anonKey,Authorization:'Bearer '+session.access_token}});}finally{saveSession({});dialog.close();location.reload();}};content.querySelectorAll('[data-sync]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('order-sync',{orderId:b.dataset.sync});dialog.close();showAccount();}catch(e){toast(errorMessage(e));b.disabled=false;}});return;}catch(e){if(e.message!=='SESSION_EXPIRED') {content.innerHTML=`<p class="error">${escapeHtml(errorMessage(e))}</p>`;return;}saveSession({});}}
 content.innerHTML=`<p class="muted">${tr('Masuk untuk menyimpan akses workspace dan melihat transaksi.','Sign in to access your workspaces and orders.')}</p><form id="auth-form"><label>Email<input type="email" name="email" autocomplete="email" required></label><label>${tr('Kata sandi','Password')}<input type="password" name="password" autocomplete="current-password" required minlength="8"></label><label>Kode afiliasi (opsional)<input name="referral" value="${escapeHtml(sessionStorage.getItem('om-affiliate-invite') || '')}" maxlength="12" autocapitalize="characters" autocomplete="off"></label><div class="row"><button class="btn primary" name="mode" value="login">${tr('Masuk','Sign in')}</button><button class="btn" name="mode" value="signup">${tr('Buat akun','Create account')}</button></div><p id="auth-status" role="status"></p></form>`;content.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,mode=e.submitter.value,fd=new FormData(form);form.querySelectorAll('button').forEach(b=>b.disabled=true);const referral=String(fd.get('referral')||'').trim().toUpperCase(); sessionStorage.setItem('om-affiliate-invite',referral);try{const d=await authRequest(mode==='signup'?'signup':'token?grant_type=password',{email:fd.get('email'),password:fd.get('password')});saveSession(d);if(session){await recordReferral(referral);document.dispatchEvent(new Event('om-login'));dialog.close();showAccount();}else form.querySelector('#auth-status').textContent=tr('Periksa email untuk konfirmasi akun, lalu masuk kembali.','Check your email to confirm your account, then sign in.');}catch{form.querySelector('#auth-status').textContent=tr('Tidak dapat masuk atau mendaftar. Periksa email, kata sandi, dan konfirmasi email Anda.','Could not sign in or register. Check your email, password, and email confirmation.');}finally{form.querySelectorAll('button').forEach(b=>b.disabled=false);}};
}
async function openProduct(id){await ready;const p=products.find(x=>x.id===id),dialog=document.querySelector('#purchase-dialog'),content=document.querySelector('#purchase-content');if(!p)return;content.innerHTML=`<p class="eyebrow">${escapeHtml(p.category)} / PREMIUM</p><h3>${escapeHtml(p.title)}</h3><p class="product-price">${money(p.price_idr)} <small>${tr('sekali bayar','one-time payment')}</small></p><p>${escapeHtml(tr(p.description,p.en||p.description))}</p><div class="notice">${config.checkoutEnabled?tr('Bayar melalui QRIS atau Virtual Account. Akses diberikan setelah pembayaran diverifikasi.','Pay with QRIS or Virtual Account. Access is granted after payment verification.')+(config.paymentEnvironment==='sandbox'?'<br><strong>SANDBOX — '+tr('Hanya simulasi. Jangan kirim uang nyata.','Test only. Do not send real money.')+'</strong>':''):tr('Pembayaran belum dibuka. Jangan mengirim uang. Simulator gratis tetap tersedia.','Payments are not open yet. Do not send money. The free simulator is available.')}</div><div class="row" style="margin-top:22px"><a href="workspace.html" class="btn">${tr('Coba gratis','Try for free')}</a><button id="buy" class="btn primary" ${config.checkoutEnabled?'':'disabled'}>${tr('Beli akses','Buy access')}</button></div><p id="payment-status" role="status"></p>`;dialog.showModal();if(!session){const btn=document.createElement('button');btn.className='btn';btn.textContent=tr('Masuk sebagai admin / pemilik','Sign in as admin / owner');btn.onclick=()=>{dialog.close();showAccount();};content.querySelector('.row')?.append(btn);}if(session){try{const me=await api('me');if(me.admin||me.access.some(a=>a.product_id===id)){content.querySelector('#buy').outerHTML=`<a class="btn primary" href="workspace.html?product=${encodeURIComponent(id)}">${tr('Buka workspace','Open workspace')}</a>`;return;}}catch{}}
 content.querySelector('#buy').onclick=async e=>{if(!session){dialog.close();showAccount();return;}const b=e.currentTarget;b.disabled=true;try{const order=await api('checkout',{productId:id});await loadSnap();window.snap.pay(order.token,{onSuccess:()=>pending(order.orderId),onPending:()=>pending(order.orderId),onError:()=>{toast(tr('Pembayaran belum selesai. Periksa transaksi di akun.','Payment is incomplete. Check orders in your account.'));b.disabled=false;},onClose:()=>{b.disabled=false;}});}catch(e){content.querySelector('#payment-status').textContent=errorMessage(e);b.disabled=false;}};
 async function pending(orderId){content.querySelector('#payment-status').textContent=tr('Menunggu verifikasi pembayaran. Periksa status di Akun saya.','Waiting for payment verification. Check My account for status.');try{await api('order-sync',{orderId});}catch{}dialog.close();showAccount();}
}
let snapPromise;function loadSnap(){if(window.snap)return Promise.resolve();if(!snapPromise)snapPromise=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=config.paymentEnvironment==='production'?'https://app.midtrans.com/snap/snap.js':'https://app.sandbox.midtrans.com/snap/snap.js';s.dataset.clientKey=config.clientKey;s.onload=resolve;s.onerror=()=>{snapPromise=null;s.remove();reject(new Error('SNAP_UNAVAILABLE'));};document.head.append(s);});return snapPromise;}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('[data-account]').forEach(b=>b.onclick=showAccount);document.querySelector('#language')?.addEventListener('click',()=>{lang=lang==='id'?'en':'id';localStorage.setItem('om-language',lang);translate();document.dispatchEvent(new Event('om-language'));});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderProducts();});document.querySelectorAll('[data-model-action]').forEach(b=>b.onclick=()=>{document.querySelector('#hero-model').contentWindow.postMessage({type:'om-hero',action:b.dataset.modelAction},location.origin);document.querySelectorAll('[data-model-action]').forEach(x=>x.classList.toggle('active',x===b));});translate();
addEventListener('message',e=>{const f=document.querySelector('#hero-model');if(!f||e.origin!==location.origin||e.source!==f.contentWindow||e.data?.type!=='om-model-status')return;if(!e.data.ready){document.querySelector('.outline-label').textContent='PREVIEW';document.querySelector('.visual-bottom p').dataset.i18n='staticPreview';document.querySelector('.visual-bottom p').textContent=tr('Pratinjau statis · WebGL tidak tersedia','Static preview · WebGL unavailable');document.querySelectorAll('[data-model-action]').forEach(b=>b.disabled=true);}});
ready.then(()=>{const id=new URLSearchParams(location.search).get('product');if(id&&document.querySelector('#purchase-dialog')&&products.some(p=>p.id===id&&!p.is_free))openProduct(id);document.querySelector('#hero-model')?.contentWindow.postMessage({type:'om-hero',action:'status'},location.origin);});
